async function sdkFixture({deleteStatus=200,foreignAck=false}={}){
 let user=null,sessions=[],gone=false,revoke=false;const calls=[];
 const proof=()=>({provenance:{namespace:ctx.namespace,sourceSha:ctx.sourceSha,systemIdentifier:ctx.systemIdentifier,database:"postgres",currentUser:"postgres",serverVersion:170011,markerRows:1,allMarkers:1},users:user?[{id:user.id,email:user.email,metadata:user.app_metadata,role:"authenticated",anonymous:false,deleted:null}]:[],sessions,refreshUsers:sessions.map(s=>s.user_id),roles:user?[{user_id:user.id,role:"user"}]:[],moderation:user?[{user_id:user.id,status:"active",must_change_password:false}]:[],profiles:user?[user.id]:[],preferences:user?[user.id]:[],passwordReceipts:[],passwordEvents:[],otherRows:0});
 const transport=async(url,init)=>{calls.push({path:new URL(url).pathname,method:init.method});const path=new URL(url).pathname;if(path==="/auth/v1/admin/users"&&init.method==="POST"){const body=JSON.parse(init.body);user={...body,role:"authenticated",is_anonymous:false};return Response.json(user);}if(path==="/auth/v1/user")return Response.json(user);if(path==="/rest/v1/rpc/my_access_state")return Response.json({user_id:user.id,role:"user",must_change_password:false,entitlements:{}});if(path==="/auth/v1/logout"){sessions=[];revoke=true;return new Response(null,{status:204});}if(path.startsWith("/auth/v1/admin/users/")&&init.method==="GET")return gone?Response.json({code:"user_not_found",msg:"synthetic"},{status:404,headers:{"x-supabase-api-version":"2024-01-01"}}):Response.json(user);if(path.startsWith("/auth/v1/admin/users/")&&init.method==="DELETE"){assert.equal(revoke,true);gone=true;user=null;return deleteStatus===204?new Response(null,{status:204}):Response.json(foreignAck?{id,email:"foreign@example.invalid",role:"authenticated",is_anonymous:false,app_metadata:{sc_admin_native_fixture:"foreign"}}:{},{status:deleteStatus});}throw Error("UNEXPECTED_FIXED_TEST_REQUEST");};
 const harness=await createRecoveryHarness(ctx,{query:async()=>proof(),cleanupAllowed:()=>true,transport,mailFetch:async()=>Response.json({start:0,total:0,messages_count:0,messages:[]})});
 const owner=await harness.fixture(),sid="33333333-3333-4333-8333-333333333333",exp=Math.floor(Date.now()/1000)+3600,token=[Buffer.from(JSON.stringify({alg:"HS256",typ:"JWT"})).toString("base64url"),Buffer.from(JSON.stringify({sub:owner.id,session_id:sid,role:"authenticated",exp})).toString("base64url"),Buffer.from("synthetic").toString("base64url")].join(".");sessions=[{id:sid,user_id:owner.id}];await harness.verifySession({sessionId:sid,accessToken:token,expiresAt:exp*1000});for(const stage of RECOVERY_STAGES.slice(0,7))harness.state.stage(stage);return{harness,calls};
}
